// Work out whether each release is a major, a minor or a patch, straight from the version
// string. A version ending .0.0 is a major, x.y.0 a minor, anything else a patch. Pre-releases
// (1.0.0-rc.1) are called out separately so they never look like a stable major.
// No model and no API key — edit the rules here if your registry versions differently.
const out = [];

for (const item of $input.all()) {
  const p = item.json;
  const version = String(p.version || '');
  const core = version.split('-')[0];
  const parts = core.split('.').map((n) => parseInt(n, 10));
  const [major, minor, patch] = [parts[0] || 0, parts[1] || 0, parts[2] || 0];

  let bumpType = 'patch';
  if (version.includes('-')) bumpType = 'prerelease';
  else if (minor === 0 && patch === 0) bumpType = 'major';
  else if (patch === 0) bumpType = 'minor';

  // 0.x releases are not stable, whatever the numbers say, and treating a 0.3.0 as a "minor"
  // oversells it. Say so rather than letting it through as routine.
  const preStable = major === 0;

  const label = { major: 'Major release', minor: 'New features', patch: 'Fix release', prerelease: 'Pre-release' }[bumpType];

  out.push({
    json: {
      ...p,
      bumpType,
      preStable,
      releaseLabel: preStable && bumpType !== 'prerelease' ? label + ' (pre-1.0, expect breakage)' : label,
      monthlyDownloads: Number(p.monthlyDownloads) || 0,
    },
  });
}

return out;

